1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioResult = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const INSURANCE_VALUES: Record<string, number> = {
68	  sword: 1000,
69	  amulet: 600,
70	  staff: 800,
71	  potion: 400,
72	  rune: 250,
73	  moonstone: 250,
74	};
75	
76	const DEDUCTIBLE_PER_DAMAGE = 100;
77	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
78	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
79	const FULL_REIMBURSEMENT_RATE = 1;
80	const CAP_MULTIPLIER = 2;
81	
82	const CURSE_SURCHARGE_RATE = 0.5;
83	const HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
84	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
85	const LOYALTY_YEARS_THRESHOLD = 2;
86	const LOYALTY_DISCOUNT_RATE = 0.2;
87	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
88	
89	const BLOCK_SIZE = 3;
90	const BLOCK_BASE_PREMIUM = 60;
91	
92	const basePremiumForType = (type: string): number => BASE_PREMIUMS[type];
93	
94	const itemBasePremium = (item: Item): number => basePremiumForType(item.type);
95	
96	const countByType = (items: Item[]): Map<string, number> => {
97	  const counts = new Map<string, number>();
98	  for (const item of items) {
99	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
100	  }
101	  return counts;
102	};
103	
104	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
105	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
106	
107	const groupBasePremium = (type: string, count: number): number =>
108	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
109	
110	const policyBasePremium = (items: Item[]): number =>
111	  [...countByType(items)].reduce(
112	    (total, [type, count]) => total + groupBasePremium(type, count),
113	    0,
114	  );
115	
116	// The MHPCO rounds in its own favour: premiums up, payouts down.
117	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
118	const roundDownInMHPCOsFavour = (amount: number): number => Math.floor(amount);
119	
120	// Item-scoped surcharge clauses. Each applies, independently and additively,
121	// to the affected item's own base premium.
122	const ITEM_SURCHARGE_CLAUSES: {
123	  applies: (item: Item) => boolean;
124	  rate: number;
125	}[] = [
126	  {
127	    applies: (item) => item.cursed === true,
128	    rate: CURSE_SURCHARGE_RATE,
129	  },
130	  {
131	    applies: (item) =>
132	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD,
133	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
134	  },
135	];
136	
137	const itemSurcharge = (item: Item): number => {
138	  const base = itemBasePremium(item);
139	
140	  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
141	    (total, clause) => total + base * clause.rate,
142	    0,
143	  );
144	};
145	
146	const itemSurcharges = (items: Item[]): number =>
147	  items.reduce((total, item) => total + itemSurcharge(item), 0);
148	
149	// Everything a policy-scoped clause may inspect.
150	type Policy = {
151	  items: Item[];
152	  customer: Customer;
153	  isFollowUpContract: boolean;
154	};
155	
156	// Policy-scoped modifier clauses. Each applies, independently and additively,
157	// to the policy base premium. A negative rate is a discount.
158	const POLICY_MODIFIER_CLAUSES: {
159	  applies: (policy: Policy) => boolean;
160	  rate: number;
161	}[] = [
162	  {
163	    applies: () => true,
164	    rate: FIRST_INSURANCE_SURCHARGE_RATE,
165	  },
166	  {
167	    applies: (policy) =>
168	      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
169	    rate: -LOYALTY_DISCOUNT_RATE,
170	  },
171	  {
172	    applies: (policy) => policy.isFollowUpContract,
173	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
174	  },
175	];
176	
177	const policyModifiers = (policy: Policy, policyBase: number): number =>
178	  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
179	    (total, clause) => total + policyBase * clause.rate,
180	    0,
181	  );
182	
183	const quote = (policy: Policy): QuoteResult => {
184	  const policyBase = policyBasePremium(policy.items);
185	  const modifiedPremium =
186	    policyBase + itemSurcharges(policy.items) + policyModifiers(policy, policyBase);
187	
188	  return {
189	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
190	  };
191	};
192	
193	const insuranceSum = (items: Item[]): number =>
194	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
195	
196	// A policy issued by a quote step, tracked so later claims can draw on its cap.
197	type IssuedPolicy = {
198	  items: Item[];
199	  remainingCap: number;
200	};
201	
202	// The cap a fresh policy starts with: a multiple of the insured items' value,
203	// independent of any premium modifiers.
204	const issuePolicy = (items: Item[]): IssuedPolicy => ({
205	  items,
206	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
207	});
208	
209	// Item-scoped reimbursement clauses. Unlike the additive premium surcharges,
210	// these compete: the first applicable clause sets the rate outright, so list
211	// order is precedence. An item no clause applies to is reimbursed in full.
212	//
213	// The spec's dragon-material clause ("fully reimbursed") is deliberately not
214	// listed. Full reimbursement is already the default, and where it would
215	// collide with the high-enchantment clause the spec says the 50 % rule wins —
216	// which is what precedence gives. A dragon row would therefore be
217	// unreachable: no input distinguishes its presence from its absence.
218	const ITEM_REIMBURSEMENT_CLAUSES: {
219	  applies: (item: Item) => boolean;
220	  rate: number;
221	}[] = [
222	  {
223	    applies: (item) =>
224	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD,
225	    rate: HIGH_ENCHANTMENT_REIMBURSEMENT_RATE,
226	  },
227	];
228	
229	const reimbursementRate = (item: Item): number =>
230	  ITEM_REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.rate ??
231	  FULL_REIMBURSEMENT_RATE;
232	
233	// Reimbursement clauses read the damaged item, so a claim resolves each
234	// damage entry back to the insured item it refers to.
235	const reimbursedAmount = (item: Item, amount: number): number =>
236	  amount * reimbursementRate(item);
237	
238	// A damage entry resolved to the one insured item it is settled against.
239	type DamagedItem = {
240	  item: Item;
241	  amount: number;
242	};
243	
244	// Each damage entry is settled against a *distinct* insured item, so a claim
245	// cannot draw on the same item twice. Pairing every entry up front — rather
246	// than resolving items one at a time while totalling — keeps the "each item is
247	// claimed at most once" rule in a single place, and leaves the payout
248	// arithmetic below free of the bookkeeping.
249	const pairDamagesWithInsuredItems = (
250	  damages: Damage[],
251	  items: Item[],
252	): DamagedItem[] => {
253	  const unclaimed = [...items];
254	
255	  return damages.map((damage) => {
256	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
257	    if (index === -1) {
258	      throw new Error(
259	        `the policy does not cover a further ${damage.itemType} to claim against`,
260	      );
261	    }
262	
263	    return { item: unclaimed.splice(index, 1)[0], amount: damage.amount };
264	  });
265	};
266	
267	// Each damaged item carries its own deductible, and a damage smaller than the
268	// deductible contributes nothing rather than clawing money back off the claim.
269	const payoutFor = ({ item, amount }: DamagedItem): number =>
270	  Math.max(0, reimbursedAmount(item, amount) - DEDUCTIBLE_PER_DAMAGE);
271	
272	// What the incident claims, before the policy's cap is applied.
273	const claimedAmount = (incident: Incident, items: Item[]): number =>
274	  pairDamagesWithInsuredItems(incident.damages, items).reduce(
275	    (total, damaged) => total + payoutFor(damaged),
276	    0,
277	  );
278	
279	// A claim draws its payout down from the policy's remaining cap, so the
280	// policy carries less cover into any later claim against it.
281	const drawDownCap = (policy: IssuedPolicy, payout: number): IssuedPolicy => ({
282	  ...policy,
283	  remainingCap: policy.remainingCap - payout,
284	});
285	
286	// Settling a claim pays out what the incident claims, but never more cover
287	// than the policy has left. Returns the payout alongside the drawn-down
288	// policy, leaving it to the caller to record.
289	const settleClaim = (
290	  incident: Incident,
291	  policy: IssuedPolicy,
292	): { result: ClaimResult; policy: IssuedPolicy } => {
293	  const payout = roundDownInMHPCOsFavour(
294	    Math.min(claimedAmount(incident, policy.items), policy.remainingCap),
295	  );
296	  const settled = drawDownCap(policy, payout);
297	
298	  return {
299	    result: { payout, remainingCap: settled.remainingCap },
300	    policy: settled,
301	  };
302	};
303	
304	export const runScenario = (scenario: Scenario): ScenarioResult => {
305	  let hasIssuedContract = false;
306	  const policies = new Map<number, IssuedPolicy>();
307	
308	  const results = scenario.steps.map((step, index): StepResult => {
309	    if (step.op === "claim") {
310	      const { result, policy } = settleClaim(
311	        step.incident,
312	        policies.get(step.policy)!,
313	      );
314	      policies.set(step.policy, policy);
315	
316	      return result;
317	    }
318	
319	    policies.set(index, issuePolicy(step.items));
320	
321	    const result = quote({
322	      items: step.items,
323	      customer: scenario.customer,
324	      isFollowUpContract: hasIssuedContract,
325	    });
326	    hasIssuedContract = true;
327	
328	    return result;
329	  });
330	
331	  return { results };
332	};
